parameters.functionCode:
// Extract company name from task subject
const subject = $input.first().json.subject || '';

// Remove 'Research on ' prefix and trim
let companyName = subject.replace(/^Research on\s*/i, '').trim();

// Clean up any extra characters
companyName = companyName.replace(/["']/g, '');

// If no company name found, use a default
if (!companyName) {
  companyName = 'Unknown Company';
}

return {
  json: {
    companyName: companyName,
    originalSubject: subject,
    taskId: $input.first().json.id,
    taskVersion: $input.first().json.version || 1
  }
};

// Get input data
const data = $input.first().json;
const companyName = data.companyName;
const sections = data.sections;
const taskId = data.taskId;
const taskVersion = data.taskVersion;

// Generate sample research data for each section
const results = sections.map(section => {
  // 20% chance of being missing
  const isMissing = Math.random() < 0.2;

  if (isMissing) {
    return {
      section: section,
      status: 'Missing',
      data: null,
      evidence: null
    };
  } else {
    // Generate sample data based on section
    let sampleData = '';
    let evidenceFile = '';

    switch(section) {
      case 'Introduction':
        sampleData = `${companyName} is a well-established company operating in its respective industry. This comprehensive research provides an overview of the company's structure, operations, and market position.`;
        evidenceFile = 'introduction_overview.pdf';
        break;
      case 'Company Overview':
        sampleData = `${companyName} operates as a [INDUSTRY TYPE] company with headquarters located in [LOCATION]. The company serves [TARGET MARKET] and has been in operation since [YEAR].`;
        evidenceFile = 'company_profile.pdf';
        break;
      case 'Financial Performance':
        sampleData = `Recent financial analysis shows ${companyName} has demonstrated [PERFORMANCE TREND] over the past fiscal year with revenue of approximately [AMOUNT] and a [PROFIT/LOSS] margin.`;
        evidenceFile = 'financial_statements.xlsx';
        break;
      case 'Management Team':
        sampleData = `The leadership team of ${companyName} consists of experienced professionals with backgrounds in [RELEVANT FIELDS]. Key executives include CEO, CFO, and department heads.`;
        evidenceFile = 'management_bios.pdf';
        break;
      case 'Market Analysis':
        sampleData = `${companyName} operates in a [MARKET SIZE] market with [GROWTH RATE] annual growth. The company holds approximately [MARKET SHARE]% market share in its primary segment.`;
        evidenceFile = 'market_research.pdf';
        break;
      case 'Competitive Landscape':
        sampleData = `The competitive environment for ${companyName} includes [NUMBER] major competitors. Key differentiators include [UNIQUE SELLING POINTS].`;
        evidenceFile = 'competitor_analysis.xlsx';
        break;
      case 'Legal Structure and Compliance':
        sampleData = `${companyName} is incorporated as a [LEGAL ENTITY TYPE] and maintains compliance with [RELEVANT REGULATIONS]. No major legal issues identified.`;
        evidenceFile = 'legal_documents.pdf';
        break;
      case 'Intellectual Property':
        sampleData = `${companyName} holds [NUMBER] patents, [NUMBER] trademarks, and [NUMBER] copyrights related to its core business operations.`;
        evidenceFile = 'ip_portfolio.pdf';
        break;
      case 'Operational Risks':
        sampleData = `Key operational risks for ${companyName} include supply chain dependencies, regulatory changes, and market volatility. Mitigation strategies are in place.`;
        evidenceFile = 'risk_assessment.pdf';
        break;
      default:
        sampleData = `Research data for ${section} shows ${companyName} maintains [POSITIVE/NEGATIVE] indicators in this area. Further analysis may be required for complete assessment.`;
        evidenceFile = `${section.toLowerCase().replace(/\s+/g, '_')}_report.pdf`;
    }

    return {
      section: section,
      status: 'Completed',
      data: sampleData,
      evidence: evidenceFile
    };
  }
});

// Create the final research report
const researchReport = {
  company: companyName,
  results: results,
  timestamp: new Date().toISOString(),
  summary: {
    totalSections: sections.length,
    completedSections: results.filter(r => r.status === 'Completed').length,
    missingSections: results.filter(r => r.status === 'Missing').length,
    completionRate: `${Math.round((results.filter(r => r.status === 'Completed').length / sections.length) * 100)}%`
  },
  taskId: taskId,
  taskVersion: taskVersion
};

return {
  json: researchReport
};

